{
  "schema_version": 1,
  "template_id": "product-feedback-coordinator",
  "template_version": 3,
  "checks": [
    {
      "id": "identity",
      "title": "Confirm product owner and Crew identity",
      "instructions": "Confirm whether this capability seeds a Product Crew or extends a compatible Crew. Preserve existing identity and name the accountable product decision owner."
    },
    {
      "id": "skill",
      "title": "Verify selected skill",
      "instructions": "Confirm skills/product-feedback-coordinator/SKILL.md exists and product-feedback-coordinator is selected for this Crew."
    },
    {
      "id": "scope",
      "title": "Bind one product decision route",
      "instructions": "Record whether this setup certifies feedback-theme or released-feature adoption, plus tenant, product, feature or journey, period, affected segment, exact source artifact ID and owner. The other route remains unverified until its own source, rule, first result and review checks are repeated. Minimum input: Validated feedback theme or feature-adoption observation, exact product and segment, current issue/release source, product owner and decision criteria."
    },
    {
      "id": "access",
      "title": "Probe the selected product evidence route",
      "instructions": "Feedback route: read one validated theme by artifact ID, its deduplicated case or survey source IDs, eligible response denominator and contrary examples, then the current issue and roadmap records for the same product and segment. Record revisions and observed times; a related issue title is not an exact issue match. Released-feature route: read the validated observation artifact, exact deployed release/build and flag revision, eligible and exposed account sets, versioned use event rule, observation window and current issue state. Check account identity, exclusions, coverage and source lag under the same segment. Complete only the selected route; record its source IDs, timestamps, permissions and gaps. Helpdesk/survey exports, product usage and exposure records, release/flag source, issue tracker and roadmap through scoped MCPs or files. A read-only first decision uses authorized exports."
    },
    {
      "id": "policy",
      "title": "Verify the selected decision rule",
      "instructions": "Recompute the theme prevalence from the stated population, keep linked support cases separate from survey respondents, and show why a current issue is exact, related or unmatched. Setup remains pending if a missing denominator becomes “everyone,” a related issue becomes a fix, or a customer promise is drafted without owner authority. Recompute used/exposed and exposed/eligible rates, compare only windows with the same rule and mature coverage, and label one complete window a baseline. Setup remains pending if missing exposure or use events are treated as zero, an immature window yields a winner, or a metric change is called causal. Complete only the selected route; record strategic criteria, privacy limits and action authority. Do not promise a feature, rank a roadmap by mention count alone, create or close an issue, change priority, publish a plan, or message a customer without owner approval and a separate route."
    },
    {
      "id": "first_result",
      "title": "Produce a sourced first decision brief",
      "instructions": "Produce A product decision brief with exact source artifact, affected scope, current issue state, evidence gaps, owner options and next verification. Cite each claim, applicable denominator, release and source revision. A fictional example does not complete this check."
    },
    {
      "id": "review",
      "title": "Review with product owner",
      "instructions": "Show representative and contrary evidence, exact existing issue match, unknowns, options and recommended next investigation. Record the owner decision or correction."
    },
    {
      "id": "delivery",
      "title": "Choose read-only or issue route",
      "optional": true,
      "instructions": "Read-only chat completes this choice. Any issue creation, status change or customer communication needs a separately approved exact-object route and provider receipt."
    },
    {
      "id": "recurrence",
      "title": "Choose manual or recurring review",
      "optional": true,
      "instructions": "Manual-only completes this choice. A schedule or authenticated event requires reviewed source scope, stable theme or feature IDs, deduplication, cost and notification rules. Re-read current issue, roadmap, release and product evidence; retain theme or feature observation IDs, rule versions and owner decisions, and report changes instead of opening duplicate work."
    }
  ],
  "completed_steps": []
}

files.templates/product-discovery-researcher/T:
{
  "schema_version": 1,
  "template_id": "product-discovery-researcher",
  "template_version": 1,
  "checks": [
    {
      "id": "identity",
      "title": "Confirm role and owner",
      "instructions": "Confirm whether Product Discovery Researcher seeds this Crew or extends a compatible Crew. Preserve its existing identity and name the accountable Product owner."
    },
    {
      "id": "skill",
      "title": "Verify the selected skill",
      "instructions": "Confirm skills/product-discovery-researcher/SKILL.md exists and product-discovery-researcher is selected."
    },
    {
      "id": "scope",
      "title": "Bind one first job",
      "instructions": "Record exact product or offer, tenant, segment, period, policy version, source IDs, decision owner and exclusions. Minimum input: Product and segment, research question, authorized interview or case records, observation period, privacy policy and product owner."
    },
    {
      "id": "access",
      "title": "Prove the source join",
      "instructions": "Read two dated observations for the same product and segment, their participant or account IDs and consent scope, plus one contrary or missing case. Record source revisions and distinguish a linked ticket from an independent respondent. Research repository, helpdesk, CRM and product analytics through scoped access; supplied interview notes and exports work for a first read-only brief. Record permission and observed time; missing access stays blocked."
    },
    {
      "id": "policy",
      "title": "Verify the hard acceptance rule",
      "instructions": "Recount unique participants and cases, cite one contrary observation and label sample limits. Reject a population prevalence or solution claim without a defined denominator and owner decision. Do not recruit or contact participants, publish quotations, promise a feature or change a roadmap without an approved route and privacy review."
    },
    {
      "id": "first_result",
      "title": "Produce a first sourced result",
      "instructions": "Use real authorized records to produce An opportunity brief linking one customer problem to source records, affected segment, contrary evidence, assumptions and a product-owner research decision. A fictional example does not complete this check."
    },
    {
      "id": "review",
      "title": "Review with the accountable owner",
      "instructions": "Show source IDs, contrary evidence, uncertainty, rejected options and proposed next action; record the owner decision or correction."
    },
    {
      "id": "delivery",
      "title": "Choose the action route",
      "optional": true,
      "instructions": "Read-only chat completes this choice. Writes, publication, contact and money actions require separate exact-object approval and provider receipts. Do not recruit or contact participants, publish quotations, promise a feature or change a roadmap without an approved route and privacy review."
    },
    {
      "id": "recurrence",
      "title": "Choose manual or recurring work",
      "optional": true,
      "instructions": "Manual-only completes this choice. A schedule or event requires stable IDs, deduplication, cost and notification rules, reviewed by the owner. Reuse stable participant, case and opportunity IDs; add only newly authorized observations and preserve changed hypotheses and owner decisions."
    }
  ],
  "completed_steps": []
}

